public sealed class Cache<T> where T : notnull
{
    private readonly Dictionary<string, T> _items = new();
    public T Get(string key) => _items[key] ?? throw new InvalidOperationException($"Missing {key}");
}

using UnityEngine;

public sealed class PlayerMover : MonoBehaviour
{
    [SerializeField] private float speed = 6.5f;
    private void Update() => transform.position += speed * Time.deltaTime * Vector3.forward;
}

from pathlib import Path

def changed(paths: list[Path]) -> dict[str, int]:
    return {path.as_posix(): path.stat().st_size for path in paths if path.exists()}

